"""Reproduce teaching SVGs and extract Figure 3 from the supplied journal PDF.
Requires Python 3 and pdftoppm (e.g. nix shell nixpkgs#poppler-utils).
"""
from pathlib import Path
from html import escape
import subprocess
out=Path(__file__).resolve().parents[1]/'public/figures/double-descent'
out.mkdir(parents=True,exist_ok=True)
def text(x,y,s,size=19): return f'<text x="{x}" y="{y}" font-size="{size}">{escape(s)}</text>'
def box(x,y,a,b,c='#ddd9fa',w=270):
 return f'<rect x="{x}" y="{y}" width="{w}" height="90" rx="12" fill="{c}" stroke="#71849a"/>'+text(x+12,y+32,a)+text(x+12,y+65,b,16)
def arrow(x,y,a,b): return f'<path d="M{x} {y} L{a} {b}" stroke="#53677d" stroke-width="3" fill="none" marker-end="url(#a)"/>'
def svg(name,title,desc,body,h=440):
 (out/f'{name}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 940 {h}" role="img" aria-labelledby="t d"><title id="t">{escape(title)}</title><desc id="d">{escape(desc)}</desc><defs><marker id="a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#53677d"/></marker></defs><rect width="940" height="{h}" rx="18" fill="#f3f6fb"/><g font-family="Arial,sans-serif" fill="#17304b">'+text(28,43,title,25)+body+'</g></svg>')
svg('problem','01 / A second descent changes the question','Schematic test-error curve; no measured coordinates.',arrow(65,345,880,345)+arrow(65,345,65,85)+text(80,95,'Test error',18)+text(650,380,'Effective complexity →',18)+'<path d="M90 145 C170 350 250 300 330 235 S425 65 470 125 S530 310 850 320" fill="none" stroke="#8264b0" stroke-width="5"/><path d="M460 100 V345" stroke="#bc6d28" stroke-dasharray="6 6"/>'+text(100,325,'Underfitting',17)+text(350,80,'Barely fits the data',18)+text(640,285,'Many possible fits',18)+text(30,420,'The peak is near the fitting threshold—not a fixed universal parameter count.',18))
svg('architecture','02 / The five-layer CNN: a complete functional path','Source Appendix B.1 CNN; dimensions derived for CIFAR input and listed pooling sizes.',box(30,95,'A · CIFAR input','B × 3 × 32 × 32','#d4eee7')+arrow(310,140,345,140)+box(350,95,'B · Conv / BN / ReLU','Pool 1 → B × k × 32 × 32')+arrow(630,140,665,140)+box(670,95,'C · Conv / BN / ReLU','Pool 2 → B × 2k × 16 × 16',w=240)+arrow(790,195,790,250)+box(670,260,'D · Conv / BN / ReLU','Pool 2 → B × 4k × 8 × 8',w=240)+arrow(660,305,630,305)+box(350,260,'E · Conv / BN / ReLU','Pool 8 → B × 8k × 1 × 1')+arrow(340,305,310,305)+box(30,260,'F · Flatten + linear','B × C logits → probabilities','#ffe6cb')+text(30,405,'All convolutions: 3 × 3, stride 1, padding 1. C = 10 or 100 classes.',18))
svg('training','03 / Same predictor, different experimental paths','Train with observed labels; measure errors; freeze parameters and normalization state at inference.',box(30,100,'Train · X and fixed labels','Augment X when configured','#d4eee7')+arrow(310,145,345,145)+box(350,100,'A → F · Cross-entropy','Backpropagate through CNN')+arrow(630,145,665,145)+box(670,100,'G · Optimizer update','Carry weights and state',w=240)+box(30,270,'Infer · New clean X','No label input; freeze model','#d4eee7')+arrow(310,315,345,315)+box(350,270,'A → F · Forward only','Probabilities → argmax')+arrow(630,315,665,315)+box(670,270,'H · Evaluation','Compare to held-out label','#ffe6cb',240)+text(30,414,'Width sweep: fresh models. Epoch sweep: checkpoints of the same training run.',18))
svg('representation','04 / What does width actually change?','CNN activation sizes at stage E and F; width is not effective model complexity.',box(30,105,'k = 8','E: B × 64 pooled features','#d4eee7',420)+arrow(465,150,485,150)+box(490,105,'F · 64 → C','A learned linear classifier',w=420)+box(30,265,'k = 16','E: B × 128 pooled features','#d4eee7',420)+arrow(465,310,485,310)+box(490,265,'F · 128 → C','Earlier convolutions also widen',w=420)+text(30,415,'Doubling k changes every stage; EMC also depends on data, optimizer and duration.',18))
svg('emc','05 / Effective model complexity belongs to a procedure','Toy estimates across independent training datasets; epsilon equals 0.1.',box(30,105,'Fix procedure T and D','Architecture, optimizer, budget','#d4eee7')+arrow(310,150,345,150)+box(350,105,'For each sample size n','Train on fresh sampled sets')+arrow(630,150,665,150)+box(670,105,'Average training error','Compare to ε = 0.1','#ffe6cb',240)+text(55,270,'Toy n',19)+text(265,270,'100',19)+text(440,270,'200',19)+text(615,270,'300',19)+text(790,270,'400',19)+text(55,325,'Mean error',19)+text(265,325,'0.02',19)+text(440,325,'0.06',19)+text(615,325,'0.09',19)+text(790,325,'0.14',19)+text(30,410,'Largest passing tested size: 300. Exact EMC needs more than this coarse grid.',18))
svg('numbers','06 / A prediction, its loss, and its fitting error','Computed teaching example at classifier F, objective G, and evaluation H.',box(30,100,'A–E · Toy features','h = (1, 2); k here abstracted','#d4eee7')+arrow(310,145,345,145)+box(350,100,'F · Two-class logits','z = (log 3, 0) → p = (.75, .25)')+arrow(630,145,665,145)+box(670,100,'G · Observed label 2','Loss = −log .25 ≈ 1.386','#ffe6cb',240)+box(30,270,'Backprop at F','∂loss/∂z = (.75, −.75)')+box(350,270,'Argmax predicts class 1','Training error = 1 on label 2')+box(670,270,'H · Clean label 1','Clean error = 0','#d4eee7',240)+text(30,415,'Fixed corrupted labels can pull a locally correct clean prediction in the wrong direction.',18))
svg('epochs','07 / Fixed width, changing fitting capacity','Schematic training-time cases; not guaranteed monotonicity or measured curves.',box(30,100,'Small model','Cannot fit the full set','#d4eee7')+box(350,100,'Medium model','Only barely fits at the end','#ffe6cb')+box(670,100,'Large model','Can pass through the peak',w=240)+''.join(f'<path d="M{x} 340 L{x+235} 340 M{x} 340 V220" stroke="#71849a" fill="none"/>' for x in (45,365,685))+'<path d="M55 235 Q120 320 265 325 M375 235 Q425 370 465 300 T585 255 M695 235 C725 360 760 220 790 260 S835 325 905 327" stroke="#8264b0" stroke-width="4" fill="none"/>'+text(75,375,'More training →',17)+text(395,375,'More training →',17)+text(715,375,'More training →',17)+text(30,420,'Weights, optimizer state and normalization statistics evolve; parameter count stays fixed.',18))
svg('samples','08 / More samples can move a model toward the peak','Toy capacity comparison only; these ratios do not compute test error.',box(30,100,'Hold T fixed','Illustrative EMC = 18,000','#d4eee7')+arrow(310,145,345,145)+box(350,100,'n = 4,000','EMC / n = 4.5')+arrow(630,145,665,145)+box(670,100,'n = 18,000','EMC / n = 1','#ffe6cb',240)+text(365,245,'Effectively overparameterized',17)+text(680,245,'Near the fitting threshold',17)+box(30,295,'Data generally helps','But the threshold also moves','#d4eee7',420)+box(490,295,'A local reversal can appear','Check width AND training duration',w=420)+text(30,435,'The real translation comparison uses 4k versus 18k sentences; its EMC is not measured here.',17),465)
subprocess.run(['pdftoppm','-f','5','-singlefile','-scale-to','2000','-x','280','-y','265','-W','770','-H','420','-png',str(out.parents[1]/'materials/afd074637ca4280b.pdf'),str(out/'source-figure-3')],check=True)
print('Generated eight teaching SVGs and source Figure 3 crop.')
